import { ofetch } from "ofetch";

const api = ofetch.create({
  baseURL: "/api",
  retry: 1,
  onRequest({ request, options }) {
    options.headers = {
      ...options.headers,
      Authorization: "Bearer " + getToken(),
    };
  },
  onResponseError({ response }) {
    console.error("Request failed", response.status);
  },
});

